1	package agentusage
2	
3	import (
4		"cmp"
5		"crypto/sha256"
6		"encoding/hex"
7		"slices"
8		"time"
9	)
10	
11	// pos orders lines the way ParseSession reads them (D3).
12	type pos struct {
13		rank string // "0" parent; "1"+agentID+"\x00"+baseName for a sub-agent
14		off  int64
15	}
16	
17	// parentRank is the rank of the parent transcript; it sorts before every
18	// sub-agent rank.
19	const parentRank = "0"
20	
21	// subAgentRank is the rank of a sub-agent's transcript: sub-agents are read by
22	// ID, then by base name.
23	func subAgentRank(agentID, name string) string { return "1" + agentID + "\x00" + name }
24	
25	// transcriptRank is subAgentRank made unique per transcript: the raw ID and
26	// the path break ties between sub-agents whose sanitized IDs and base names
27	// coincide. It is a function of the transcript alone, so it is stable from one
28	// pass to the next, and it doubles as the agent's key in a table.
29	func transcriptRank(agentID, name, rawID, path string) string {
30		return subAgentRank(agentID, name) + "\x00" + rawID + "\x00" + path
31	}
32	
33	// compare orders positions by rank, then by offset.
34	func (p pos) compare(o pos) int {
35		if c := cmp.Compare(p.rank, o.rank); c != 0 {
36			return c
37		}
38		return cmp.Compare(p.off, o.off)
39	}
40	
41	// msgKey identifies one message of a session. A message with an id is keyed
42	// by the id alone; one without is keyed by where it was read (file rank and
43	// offset).
44	type msgKey struct {
45		id   string
46		file string
47		off  int64
48	}
49	
50	// entry is the last state seen of one message. Which line is "last" is a
51	// function of positions, never of arrival.
52	type entry struct {
53		first, last pos
54		agent       string // agent ID of the last line; "" for the parent
55		file        string // base name of one file the message was seen in
56		otherFiles  []string
57		model       string
58		tokens      Tokens
59		stopNull    bool
60	}
61	
62	// addFile remembers that the message was also seen in the file named name.
63	func (e *entry) addFile(name string) {
64		if e.file == name || slices.Contains(e.otherFiles, name) {
65			return
66		}
67		e.otherFiles = append(e.otherFiles, name)
68	}
69	
70	// absorb folds o into e: the greatest position gives the state, the smallest
71	// gives first, and the files are united.
72	func (e *entry) absorb(o *entry) {
73		if o.last.compare(e.last) >= 0 {
74			e.last, e.agent, e.model, e.tokens, e.stopNull = o.last, o.agent, o.model, o.tokens, o.stopNull
75		}
76		if o.first.compare(e.first) < 0 {
77			e.first = o.first
78		}
79		e.addFile(o.file)
80		for _, f := range o.otherFiles {
81			e.addFile(f)
82		}
83	}
84	
85	// toolKey identifies one tool call of a message: its tool_use id, or, when
86	// the block has none, its place (apiBlockIndex and rank in content).
87	type toolKey struct {
88		msg, id  string
89		abi, idx int
90	}
91	
92	// boundedID returns s, or, if it is longer than maxLabelLen, the hex SHA-256 of
93	// s (64 bytes): a fixed size, and no two long ids share a key.
94	func boundedID(s string) string {
95		if len(s) <= maxLabelLen {
96			return s
97		}
98		h := sha256.Sum256([]byte(s))
99		return hex.EncodeToString(h[:])
100	}
101	
102	// toolSeen is where a tool call was last seen; the agent of the greatest
103	// position gets the call, like a message's tokens.
104	type toolSeen struct {
105		p     pos
106		agent string
107	}
108	
109	// span is the earliest and latest timestamp seen for an agent.
110	type span struct{ first, last time.Time }
111	
112	// fold widens s to include at.
113	func (s *span) fold(at time.Time) {
114		if s.first.IsZero() || at.Before(s.first) {
115			s.first = at
116		}
117		if at.After(s.last) {
118			s.last = at
119		}
120	}
121	
122	// spill totals the lines that no longer get a table entry.
123	type spill struct {
124		tokens   Tokens
125		messages int
126		partial  int
127		models   modelSet
128	}
129	
130	// issueAt is a FileIssue with the position of the line it describes.
131	type issueAt struct {
132		p  pos
133		fi FileIssue
134	}
135	
136	// compare orders issues by position, then kind, then file.
137	func (a issueAt) compare(b issueAt) int {
138		if c := a.p.compare(b.p); c != 0 {
139			return c
140		}
141		if c := cmp.Compare(a.fi.Kind, b.fi.Kind); c != 0 {
142			return c
143		}
144		return cmp.Compare(a.fi.File, b.fi.File)
145	}
146	
147	// table folds lines into per-key last states, ordered by position (D3). It
148	// is both the content of a Delta and the state of an Aggregate. Two declared
149	// exceptions to order-freedom: which no-id lines spill past maxNoIDEntries
150	// (the smallest positions of each merge are kept, see mergeCapped), and which
151	// models fill a spill's maxModelsPerAgent (arrival order).
152	type table struct {
153		entries map[msgKey]*entry
154		noID    int // entries holding a line without message id
155		spill   map[string]*spill
156		// tools holds the tool calls of lines with a message id, deduplicated by
157		// toolKey; noIDTools counts, per agent, those of lines without one (each
158		// line is its own event, so a counter is exact and needs no key). spans is
159		// the timestamp range per agent. Only tools is capped (maxToolEntries, the
160		// overflow going to extraTools); the others are bounded by the agents.
161		tools     map[toolKey]toolSeen
162		noIDTools map[string]int
163		// extraTools counts, per agent, the calls past maxToolEntries, which get
164		// no entry. Like the cap on lines without id, which calls spill follows
165		// position on a merge but arrival on a single pass.
166		extraTools map[string]int
167		spans      map[string]*span
168		// counters of lines; CrossFileDuplicates is derived by finish.
169		unreadable, noUsage, noMessageID, oversized int
170		// capped holds the unreadable/oversized issues per file name, trimmed to
171		// the maxFileIssuesPerFile smallest positions; stateIssues holds the
172		// other kinds, which occur once per file.
173		capped      map[string][]issueAt
174		stateIssues []issueAt
175		// versions maps a distinct client version to its first position, at most
176		// maxVersions of them (the smallest positions).
177		versions map[string]pos
178	}
179	
180	func newTable() *table {
181		return &table{
182			entries:    map[msgKey]*entry{},
183			spill:      map[string]*spill{},
184			tools:      map[toolKey]toolSeen{},
185			noIDTools:  map[string]int{},
186			extraTools: map[string]int{},
187			spans:      map[string]*span{},
188			capped:     map[string][]issueAt{},
189			versions:   map[string]pos{},
190		}
191	}
192	
193	// addLine decodes one line of the file named name for agent ("" for the
194	// parent) and folds it. Synthetic and ignored lines never count.
195	func (t *table) addLine(agent, name string, p pos, line []byte) {
196		r, kind := decodeLine(line)
197		if kind != kindUnreadable {
198			t.noteVersion(r.Version, p)
199			t.noteActivity(agent, p, r)
200		}
201		switch kind {
202		case kindUsage:
203			t.addUsage(agent, name, p, r)
204		case kindNoUsage:
205			t.noUsage++
206		case kindUnreadable:
207			t.unreadable++
208			t.addFileIssue(name, p, IssueUnreadable)
209		case kindIgnored, kindSynthetic:
210		}
211	}
212	
213	// noteActivity folds the timestamp and the tool calls of a readable line.
214	func (t *table) noteActivity(agent string, p pos, r record) {
215		if !r.At.IsZero() {
216			t.foldSpan(agent, r.At)
217		}
218		if r.MessageID == "" {
219			if n := countLineTools(r.Tools); n > 0 {
220				t.noIDTools[agent] += n
221			}
222			return
223		}
224		msg := boundedID(r.MessageID)
225		for _, ref := range r.Tools {
226			k := toolKey{msg: msg, id: boundedID(ref.id)}
227			// Without a tool_use id the call is keyed by place: apiBlockIndex and
228			// rank in content. Limit: with neither an id nor an apiBlockIndex, two
229			// calls of one message split over two lines both fall on idx 0 and
230			// count once (an undercount). Claude Code 2.1.302 always writes an id.
231			if ref.id == "" {
232				k.abi, k.idx = ref.abi, ref.idx
233			}
234			t.putTool(k, toolSeen{p: p, agent: agent})
235		}
236	}
237	
238	// countLineTools counts the tool calls of one line without message id: a
239	// tool_use id repeated in the line is one call, blocks without id each count.
240	func countLineTools(refs []toolRef) int {
241		seen := make(map[string]bool, len(refs))
242		n := 0
243		for _, ref := range refs {
244			if ref.id != "" && seen[ref.id] {
245				continue
246			}
247			seen[ref.id] = true
248			n++
249		}
250		return n
251	}
252	
253	// foldSpan widens the span of agent to include at.
254	func (t *table) foldSpan(agent string, at time.Time) {
255		sp := t.spans[agent]
256		if sp == nil {
257			sp = &span{}
258			t.spans[agent] = sp
259		}
260		sp.fold(at)
261	}
262	
263	// putTool keeps the greatest position seen for k. A call new to a full table
264	// is counted in extraTools instead.
265	func (t *table) putTool(k toolKey, s toolSeen) {
266		cur, ok := t.tools[k]
267		switch {
268		case ok && s.p.compare(cur.p) < 0:
269		case !ok && len(t.tools) >= maxToolEntries:
270			t.extraTools[s.agent]++
271		default:
272			t.tools[k] = s
273		}
274	}
275	
276	// maxSelectInsertion is the largest excess trimTools selects by insertion;
277	// past it a full sort is cheaper.
278	const maxSelectInsertion = 256
279	
280	// trimTools moves the entries past maxToolEntries, the greatest positions
281	// first, to extraTools. With a table already at the cap, as on every poll of
282	// a long session, the excess is small: the entries to evict are selected in
283	// one pass instead of sorting every key.
284	func (t *table) trimTools() {
285		excess := len(t.tools) - maxToolEntries
286		if excess <= 0 {
287			return
288		}
289		var evict []toolKey
290		if excess > maxSelectInsertion {
291			evict = t.sortedToolKeys()[maxToolEntries:]
292		} else {
293			evict = t.greatestToolKeys(excess)
294		}
295		for _, k := range evict {
296			t.extraTools[t.tools[k].agent]++
297			delete(t.tools, k)
298		}
299	}
300	
301	// compareTools orders two tool calls by position, then by key: a total order,
302	// so the entries kept do not depend on map iteration.
303	func (t *table) compareTools(a, b toolKey) int {
304		return cmp.Or(t.tools[a].p.compare(t.tools[b].p),
305			cmp.Compare(a.msg, b.msg), cmp.Compare(a.id, b.id), cmp.Compare(a.abi, b.abi), cmp.Compare(a.idx, b.idx))
306	}
307	
308	// sortedToolKeys returns every tool key in ascending order.
309	func (t *table) sortedToolKeys() []toolKey {
310		keys := make([]toolKey, 0, len(t.tools))
311		for k := range t.tools {
312			keys = append(keys, k)
313		}
314		slices.SortFunc(keys, t.compareTools)
315		return keys
316	}
317	
318	// greatestToolKeys returns the n greatest tool keys in ascending order,
319	// scanning the table once.
320	func (t *table) greatestToolKeys(n int) []toolKey {
321		top := make([]toolKey, 0, n)
322		for k := range t.tools {
323			if len(top) == n {
324				if t.compareTools(k, top[0]) <= 0 {
325					continue
326				}
327				copy(top, top[1:])
328				top = top[:n-1]
329			}
330			i, _ := slices.BinarySearchFunc(top, k, t.compareTools)
331			top = slices.Insert(top, i, k)
332		}
333		return top
334	}
335	
336	// addOversized counts a line longer than MaxLineBytes that started at p.
337	func (t *table) addOversized(name string, p pos) {
338		t.oversized++
339		t.addFileIssue(name, p, IssueOversized)
340	}
341	
342	// addUsage folds one usage record in.
343	func (t *table) addUsage(agent, name string, p pos, r record) {
344		key := msgKey{id: r.MessageID}
345		if r.MessageID == "" {
346			key = msgKey{file: p.rank, off: p.off}
347			t.noMessageID++
348			if _, ok := t.entries[key]; !ok {
349				if t.noID >= maxNoIDEntries {
350					t.addSpill(agent, r)
351					return
352				}
353				t.noID++
354			}
355		}
356		t.put(key, &entry{
357			first: p, last: p, agent: agent, file: name,
358			model: r.Model, tokens: r.Usage, stopNull: r.StopNull,
359		})
360	}
361	
362	// put folds e into the table under key; the table keeps its own copy.
363	func (t *table) put(key msgKey, e *entry) {
364		if cur, ok := t.entries[key]; ok {
365			cur.absorb(e)
366			return
367		}
368		c := *e
369		c.otherFiles = slices.Clone(e.otherFiles)
370		t.entries[key] = &c
371	}
372	
373	// addSpill counts a no-id line that gets no table entry.
374	func (t *table) addSpill(agent string, r record) {
375		sp := t.spill[agent]
376		if sp == nil {
377			sp = &spill{}
378			t.spill[agent] = sp
379		}
380		sp.absorbRecord(r)
381	}
382	
383	// spillEntry totals an entry that gets no slot in the table.
384	func (t *table) spillEntry(e *entry) {
385		sp := t.spill[e.agent]
386		if sp == nil {
387			sp = &spill{}
388			t.spill[e.agent] = sp
389		}
390		sp.tokens = sp.tokens.Add(e.tokens)
391		sp.messages++
392		if e.stopNull {
393			sp.partial++
394		}
395		sp.models.add(e.model)
396	}
397	
398	func (s *spill) absorbRecord(r record) {
399		s.tokens = s.tokens.Add(r.Usage)
400		s.messages++
401		if r.StopNull {
402			s.partial++
403		}
404		s.models.add(r.Model)
405	}
406	
407	// noteVersion records a client version with its first position, keeping the
408	// maxVersions smallest.
409	func (t *table) noteVersion(v string, p pos) {
410		v = sanitizeLabel(v)
411		if v == "" {
412			return
413		}
414		if cur, ok := t.versions[v]; ok {
415			if p.compare(cur) < 0 {
416				t.versions[v] = p
417			}
418			return
419		}
420		if len(t.versions) >= maxVersions {
421			worst, wp := "", pos{}
422			for k, kp := range t.versions {
423				if worst == "" || kp.compare(wp) > 0 {
424					worst, wp = k, kp
425				}
426			}
427			if p.compare(wp) >= 0 {
428				return
429			}
430			delete(t.versions, worst)
431		}
432		t.versions[v] = p
433	}
434	
435	// addFileIssue records an issue of the file named name. Unreadable and
436	// oversized ones are kept at most maxFileIssuesPerFile per file (the counters
437	// are not capped); the other kinds occur once per file and are always kept.
438	func (t *table) addFileIssue(name string, p pos, kind IssueKind) {
439		it := issueAt{p: p, fi: FileIssue{File: name, Offset: p.off, Kind: kind}}
440		if kind != IssueUnreadable && kind != IssueOversized {
441			t.stateIssues = append(t.stateIssues, it)
442			return
443		}
444		t.capped[name] = trimIssues(append(t.capped[name], it), 2*maxFileIssuesPerFile)
445	}
446	
447	// trimIssues keeps the maxFileIssuesPerFile smallest issues once s has grown
448	// to limit entries.
449	func trimIssues(s []issueAt, limit int) []issueAt {
450		if len(s) < limit {
451			return s
452		}
453		slices.SortFunc(s, issueAt.compare)
454		return s[:min(len(s), maxFileIssuesPerFile)]
455	}
456	
457	// merge folds o into t as if o's lines had been added to t. o is not modified
458	// and shares nothing with t afterwards.
459	func (t *table) merge(o *table) { t.mergeSkipping(o, nil) }
460	
461	// mergeCapped is merge with the per-session bound on lines without id: the
462	// ones o adds past maxNoIDEntries are spilled instead of getting an entry,
463	// the earliest positions being kept. Which lines spill therefore follows
464	// position, not arrival, but the totals do not depend on it.
465	func (t *table) mergeCapped(o *table) {
466		var fresh []msgKey
467		for k := range o.entries {
468			if _, had := t.entries[k]; k.id == "" && !had {
469				fresh = append(fresh, k)
470			}
471		}
472		room := max(maxNoIDEntries-t.noID, 0)
473		if len(fresh) <= room {
474			t.merge(o)
475			return
476		}
477		slices.SortFunc(fresh, func(a, b msgKey) int { return o.entries[a].first.compare(o.entries[b].first) })
478		skip := make(map[msgKey]bool, len(fresh)-room)
479		for _, k := range fresh[room:] {
480			skip[k] = true
481		}
482		t.mergeSkipping(o, skip)
483	}
484	
485	// mergeSkipping is merge, except that the entries named by skip are spilled.
486	func (t *table) mergeSkipping(o *table, skip map[msgKey]bool) {
487		for k, e := range o.entries {
488			if skip[k] {
489				t.spillEntry(e)
490				continue
491			}
492			_, had := t.entries[k]
493			t.put(k, e)
494			if !had && k.id == "" {
495				t.noID++
496			}
497		}
498		for agent, sp := range o.spill {
499			dst := t.spill[agent]
500			if dst == nil {
501				dst = &spill{}
502				t.spill[agent] = dst
503			}
504			dst.tokens = dst.tokens.Add(sp.tokens)
505			dst.messages += sp.messages
506			dst.partial += sp.partial
507			for _, m := range sp.models.list {
508				dst.models.add(m)
509			}
510		}
511		t.mergeActivity(o)
512		t.unreadable += o.unreadable
513		t.noUsage += o.noUsage
514		t.noMessageID += o.noMessageID
515		t.oversized += o.oversized
516		for name, s := range o.capped {
517			t.capped[name] = trimIssues(append(t.capped[name], s...), 2*maxFileIssuesPerFile)
518		}
519		t.stateIssues = append(t.stateIssues, o.stateIssues...)
520		for v, p := range o.versions {
521			t.noteVersion(v, p)
522		}
523	}
524	
525	// mergeActivity folds o's tool calls and spans into t.
526	func (t *table) mergeActivity(o *table) {
527		for k, s := range o.tools {
528			if cur, ok := t.tools[k]; !ok || s.p.compare(cur.p) >= 0 {
529				t.tools[k] = s // the cap is applied once below, by position
530			}
531		}
532		t.trimTools()
533		for agent, n := range o.noIDTools {
534			t.noIDTools[agent] += n
535		}
536		for agent, n := range o.extraTools {
537			t.extraTools[agent] += n
538		}
539		for agent, sp := range o.spans {
540			t.foldSpan(agent, sp.first)
541			t.foldSpan(agent, sp.last)
542		}
543	}
544	
545	// orderedKeys returns the entry keys by first position: the order messages
546	// first appear in a sequential read.
547	func (t *table) orderedKeys() []msgKey {
548		keys := make([]msgKey, 0, len(t.entries))
549		for k := range t.entries {
550			keys = append(keys, k)
551		}
552		slices.SortFunc(keys, func(a, b msgKey) int {
553			if c := t.entries[a].first.compare(t.entries[b].first); c != 0 {
554				return c
555			}
556			return cmp.Or(cmp.Compare(a.id, b.id), cmp.Compare(a.file, b.file), cmp.Compare(a.off, b.off))
557		})
558		return keys
559	}
560	
561	// finish computes the counters of the agents given (identity fields set, the
562	// parent flagged Main), the line diagnostics and the versions, all deep
563	// copies. Agents are matched by key (ID when unset); the Main agent matches
564	// the parent's "".
565	func (t *table) finish(agents []Agent) ([]Agent, Diagnostics, []string) {
566		return t.finishWith(agents, nil)
567	}
568	
569	// finishWith is finish with extra file issues, kept in position order among
570	// the table's own: a session reader passes the states of its cursors.
571	func (t *table) finishWith(agents []Agent, extra []issueAt) ([]Agent, Diagnostics, []string) {
572		out := slices.Clone(agents)
573		idx := make(map[string]int, len(out))
574		for i := range out {
575			out[i].Tokens, out[i].Models = Tokens{}, nil
576			out[i].Messages, out[i].PartialMessages = 0, 0
577			out[i].ToolCalls, out[i].FirstActivity, out[i].LastActivity = 0, time.Time{}, time.Time{}
578			id := cmp.Or(out[i].key, out[i].ID)
579			if out[i].Main {
580				id = ""
581			}
582			out[i].key = ""
583			idx[id] = i
584		}
585		models := make([]modelSet, len(out))
586		cross := 0
587		for _, k := range t.orderedKeys() {
588			e := t.entries[k]
589			cross += len(e.otherFiles)
590			if i, ok := idx[e.agent]; ok {
591				addEntry(&out[i], &models[i], e)
592			}
593		}
594		for agent, sp := range t.spill {
595			if i, ok := idx[agent]; ok {
596				addSpill(&out[i], &models[i], sp)
597			}
598		}
599		for i := range out {
600			out[i].Models = models[i].list
601		}
602		t.addActivity(out, idx)
603		return out, t.diagnostics(cross, extra), t.orderedVersions()
604	}
605	
606	// addActivity sets the tool calls and the activity span of the agents.
607	func (t *table) addActivity(out []Agent, idx map[string]int) {
608		for _, s := range t.tools {
609			if i, ok := idx[s.agent]; ok {
610				out[i].ToolCalls++
611			}
612		}
613		for _, counts := range []map[string]int{t.noIDTools, t.extraTools} {
614			for agent, n := range counts {
615				if i, ok := idx[agent]; ok {
616					out[i].ToolCalls += n
617				}
618			}
619		}
620		for agent, sp := range t.spans {
621			if i, ok := idx[agent]; ok {
622				out[i].FirstActivity, out[i].LastActivity = sp.first, sp.last
623			}
624		}
625	}
626	
627	// addEntry adds one message's final state to its agent.
628	func addEntry(ag *Agent, ms *modelSet, e *entry) {
629		ag.Tokens = ag.Tokens.Add(e.tokens)
630		ag.Messages++
631		if e.stopNull {
632			ag.PartialMessages++
633		}
634		ms.add(e.model)
635	}
636	
637	// addSpill adds a spill's totals to its agent.
638	func addSpill(ag *Agent, ms *modelSet, sp *spill) {
639		ag.Tokens = ag.Tokens.Add(sp.tokens)
640		ag.Messages += sp.messages
641		ag.PartialMessages += sp.partial
642		for _, m := range sp.models.list {
643			ms.add(m)
644		}
645	}
646	
647	// diagnostics builds the line diagnostics; cross is the number of cross-file
648	// duplicates found by finish and extra holds issues that are not the table's.
649	func (t *table) diagnostics(cross int, extra []issueAt) Diagnostics {
650		d := Diagnostics{
651			UnreadableLines: t.unreadable, OversizedLines: t.oversized,
652			NoUsage: t.noUsage, NoMessageID: t.noMessageID, CrossFileDuplicates: cross,
653		}
654		all := append(slices.Clone(t.stateIssues), extra...)
655		for _, s := range t.capped {
656			sorted := slices.Clone(s)
657			slices.SortFunc(sorted, issueAt.compare)
658			all = append(all, sorted[:min(len(sorted), maxFileIssuesPerFile)]...)
659		}
660		slices.SortFunc(all, issueAt.compare)
661		for _, it := range all {
662			d.Files = append(d.Files, it.fi)
663		}
664		return d
665	}
666	
667	// orderedVersions returns the versions by first position.
668	func (t *table) orderedVersions() []string {
669		var vs []string
670		for v := range t.versions {
671			vs = append(vs, v)
672		}
673		slices.SortFunc(vs, func(a, b string) int { return t.versions[a].compare(t.versions[b]) })
674		return vs
675	}
676	
677	// hasLines reports whether t holds anything folded from a complete line.
678	func (t *table) hasLines() bool {
679		if t == nil {
680			return false
681		}
682		return len(t.entries) > 0 || len(t.spill) > 0 || len(t.spans) > 0 || len(t.tools) > 0 || len(t.noIDTools) > 0 || len(t.extraTools) > 0 || t.unreadable+t.noUsage+t.noMessageID+t.oversized > 0
683	}
