406	
407	// Load loads the configuration from the current context
408	func Load() (*Config, error) {
409		ctx, err := GetCurrentContext()
410		if err != nil {
411			// Fallback to default on error
412			ctx = "default"
413		}
414	
415		cfg, err := LoadContext(ctx)
416		if err != nil {
417			// If the file does not exist, return the default config
418			if os.IsNotExist(err) || strings.Contains(err.Error(), "does not exist") {
419				return Default(), nil
420			}
421			// Otherwise (parsing error, permission error, etc.), propagate the error
422			return nil, err
423		}
424	
425		return cfg, nil
426	}
427	
428	// applyDefaults applies the default values to a configuration.
429	// Returns an error when the file cannot be normalized — today
430	// only for registries (duplicate slug, missing parent group).
431	func applyDefaults(cfg *Config) error {
432		homeDir, _ := os.UserHomeDir()
433	
434		// `gitlab:` → `forge:`, and it runs **first**. That is not tidiness: every
435		// default below writes into cfg.Forge, so a migration placed after them
436		// would find a block that is no longer empty and take the field-by-field
437		// path — where every field is already filled with a default, and the user's
438		// own `parallel_jobs: 7` is silently dropped. Measured, not theorised: it
439		// is what the first draft did, and the retired-keys test caught it.
440		//
441		// The other half of the reason is `docker:` → `network:`'s: yaml.Unmarshal
442		// is not strict here, so an un-migrated block is dropped in silence, and the
443		// silence would point a context at no host at all.
444		migrateGitLabSection(cfg)
445		// Before the defaults for the same reason: a default source written first
446		// would read as a value the file already carried, and the legacy one would
447		// be dropped.
448		migrateScanSection(&cfg.Scan)
449	
450		// "dark" was a third name for the built-in theme: LoadTheme accepts "",
451		// "dark" and "default" alike, but ListThemes only ever offers "default", so
452		// a config saying "dark" named a theme no picker could show. Normalised at
453		// load; LoadTheme still accepts the old name for a file not yet rewritten.
454		if cfg.App.Theme == "" || cfg.App.Theme == "dark" {
455			cfg.App.Theme = "default"
