494			cfg.Status.RefreshInterval = 10
495		}
496		if cfg.Status.Timeout == 0 {
497			cfg.Status.Timeout = 5
498		}
499		if cfg.Forge.Type == "" {
500			cfg.Forge.Type = ForgeGitLab
501		}
502		if cfg.Forge.DefaultVisibility == "" {
503			cfg.Forge.DefaultVisibility = "private"
504		}
505		if cfg.Forge.CloneMethod == "" {
506			cfg.Forge.CloneMethod = "https"
507		}
508		if cfg.Forge.Pull.ParallelJobs == 0 {
509			cfg.Forge.Pull.ParallelJobs = 4
510		}
511		if cfg.Registry.CacheDir == "" {
512			cfg.Registry.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "templates")
513		}
514		// Migrate old single-registry config to the new Registries list
515		if cfg.Registry.URL != "" && len(cfg.Registry.Registries) == 0 {
516			cfg.Registry.Registries = []RegistryItem{{
517				URL:      cfg.Registry.URL,
518				Username: cfg.Registry.Username,
519				AuthMode: AuthCredentials,
520			}}
521		}
522		if cfg.Scan.CacheDir == "" {
523			cfg.Scan.CacheDir = filepath.Join(homeDir, ".devdesk", "cache", "scans")
524		}
525		if cfg.Scan.MaxCachedReports == 0 {
526			cfg.Scan.MaxCachedReports = 50
527		}
528		if cfg.Scan.Timeout == 0 {
529			cfg.Scan.Timeout = 300
530		}
531		if cfg.Scan.MaxConcurrentScans == 0 {
532			cfg.Scan.MaxConcurrentScans = 3
533		}
534		// An address the file does not carry is the default, never "nowhere":
535		// a bind that silently does not happen would look exactly like a server
536		// that is off, and `mcp.enabled` is what answers that question.
537		if cfg.MCP.Listen == "" {
538			cfg.MCP.Listen = DefaultMCPListen
539		}
540	
541		// Auto is the historical resolution, so a config that predates the setting
542		// keeps behaving exactly as it did.
543		for _, id := range ToolIDs() {
544			if tool := cfg.Scan.Tools.Tool(id); tool.Source == "" {
545				tool.Source = ToolSourceAuto
546			}
547		}
548		if cfg.Scan.Tools.Kubeconform.KubernetesVersion == "" {
549			cfg.Scan.Tools.Kubeconform.KubernetesVersion = DefaultKubernetesVersion
550		}
551	
552		if cfg.Network.CheckTimeout == 0 {
553			cfg.Network.CheckTimeout = DefaultCheckTimeout
554		}
555		if cfg.Network.PingCount == 0 {
556			cfg.Network.PingCount = DefaultPingCount
557		}
558		if cfg.Network.CertExpiryWarnDays == 0 {
559			cfg.Network.CertExpiryWarnDays = DefaultCertExpiryWarnDays
560		}
561		if cfg.Network.PortsRefreshInterval == 0 {
562			cfg.Network.PortsRefreshInterval = DefaultPortsRefreshInterval
563		}
564		cfg.Network.ProxyPort = normalizeProxyPort(cfg.Network.ProxyPort)
565	
566		// A file with no `categories:` at all — new, or written before any scan
567		// option existed — scans for what a new context does. A block that is
568		// present is an answer, even with everything off, and is left alone: the
569		// "all off means never configured" reading of the old switches lives in the
570		// migration, which is the only place that still sees them.
571		if cfg.Scan.Categories.isZero() {
572			cfg.Scan.Categories = DefaultScanCategories()
573		}
574	
575		// Last, so that the registry migrated from the legacy single-registry keys
576		// above gets a slug like every other one.
577		return normalizeRegistries(cfg.Registry.Registries)
578	}
579	
580	// Default returns the default configuration
581	func Default() *Config {
582		homeDir, _ := os.UserHomeDir()
583		return &Config{
584			App: AppConfig{
585				Theme:           "default",
586				LogFile:         filepath.Join(homeDir, ".devdesk", "devdesk.log"),
587				DefaultView:     "dashboard",
