602				DefaultVisibility: "private",
603				CloneMethod:       "https",
604				Pull: ForgePullConfig{
605					ParallelJobs:    4,
606					IncludeArchived: false,
607				},
608			},
609			Registry: RegistryConfig{
610				CacheDir: filepath.Join(homeDir, ".devdesk", "cache", "templates"),
611			},
612			Scan: ScanConfig{
613				Categories: DefaultScanCategories(),
614				Tools: ScanTools{
615					Trivy:       TrivyConfig{ToolConfig: ToolConfig{Source: ToolSourceAuto}},
616					Gitleaks:    GitleaksConfig{ToolConfig: ToolConfig{Source: ToolSourceAuto}},
617					Plumber:     ToolConfig{Source: ToolSourceAuto},
618					Kubeconform: KubeconformConfig{ToolConfig: ToolConfig{Source: ToolSourceAuto}, KubernetesVersion: DefaultKubernetesVersion},
619					Helm:        ToolConfig{Source: ToolSourceAuto},
620					Kustomize:   ToolConfig{Source: ToolSourceAuto},
621				},
622				CacheDir:           filepath.Join(homeDir, ".devdesk", "cache", "scans"),
623				MaxCachedReports:   50,
624				Timeout:            300, // 5 minutes
625				MaxConcurrentScans: 3,
626				BaseImageTrack:     BaseImageTrackSameLine,
627			},
628			MCP: MCPConfig{
629				Listen: DefaultMCPListen,
630			},
631			Network: NetworkConfig{
