633				PingCount:            DefaultPingCount,
634				CertExpiryWarnDays:   DefaultCertExpiryWarnDays,
635				PortsRefreshInterval: DefaultPortsRefreshInterval,
636				ProxyPort:            DefaultProxyPort,
637			},
638		}
639	}
640	
641	// normalizeProxyPort returns the port to serve on: the default for a file that
642	// does not say, and the default — loudly — for one that states a port the
643	// proxy cannot bind. Unlike the other network dials, a wrong value here is not
644	// merely a slow probe: it would make every named route unbindable.
645	func normalizeProxyPort(port int) int {
646		switch {
647		case port == 0:
648			return DefaultProxyPort
649		case port < MinProxyPort || port > MaxProxyPort:
650			log.Printf("WARN [config] network.proxy_port %d is outside %d-%d, using %d",
651				port, MinProxyPort, MaxProxyPort, DefaultProxyPort)
652			return DefaultProxyPort
653		}
654		return port
655	}
