3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	
9		"github.com/charmbracelet/lipgloss"
10	
11		"github.com/anthnel/devdesk/internal/agentusage"
12		"github.com/anthnel/devdesk/internal/ui/datatable"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	const (
17		// noValue is the dash of a cell with nothing to show.
18		noValue = "-"
19		// noModel stands for an agent whose transcript named no model.
20		noModel = noValue
21		// unknownID stands for a sub-agent whose ID is empty, so it cannot be
22		// mistaken for the orchestrator, which has no short ID by design.
23		unknownID = "?"
24		// unknownType stands for a sub-agent whose meta file gave no type.
25		unknownType = "unknown"
26		// orchestratorLabel is the Agent cell of the main agent.
27		orchestratorLabel = "orchestrator"
28		// partialMark prefixes an output count that is a floor, not an exact value.
29		partialMark = "≥ "
30		// stem and lastStem draw the tree branch in front of a sub-agent's type.
31		stem     = "├─ "
32		lastStem = "└─ "
33	)
34	
35	// agentIDPrefix is the shortest agent ID shown.
36	const agentIDPrefix = 8
37	
38	// agentRow is one line of the agents table.
39	type agentRow struct {
40		agentusage.Agent
41		branch  string   // stem, lastStem, or "" (orchestrator, or a sorted list)
42		shortID string   // ID prefix, distinct within the session; "" for the orchestrator
43		share   int      // tenths of a percent of the session total, or noShare
44		key     string   // identity across rebuilds, see agentKeys
45		state   runState // what the State column shows
46	}
47	
48	// agentRows orders a session's agents (orchestrator, then sub-agents by ID),
49	// gives each its short ID and share, and draws the branches when tree is true.
50	// The sort is stable so equal IDs keep their input order.
51	func agentRows(u agentusage.Usage, tree bool, c statusClock) []agentRow {
52		var main, subs []agentusage.Agent
53		for _, a := range u.Agents {
54			if a.Main {
55				main = append(main, a)
56			} else {
57				subs = append(subs, a)
58			}
59		}
60		sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
61	
62		ordered := append(append([]agentusage.Agent{}, main...), subs...)
63		totals := make([]int64, len(ordered))
64		for i, a := range ordered {
65			totals[i] = a.Tokens.Total()
66		}
67		mainIdx := -1
68		if len(main) > 0 {
69			mainIdx = 0
70		}
71		parts := shares(totals, u.Total().Total(), mainIdx)
72	
73		ids := make([]string, len(subs))
74		for i, a := range subs {
75			ids[i] = a.ID
76		}
77		short := shortAgentIDs(ids)
78	
79		keys := agentKeys(ordered)
80		states := agentStates(ordered, c)
81		rows := make([]agentRow, 0, len(ordered))
82		for i, a := range ordered {
83			row := agentRow{Agent: a, share: parts[i], key: keys[i], state: states[i]}
84			if !a.Main {
85				j := i - len(main)
86				row.shortID = short[j]
87				if tree {
88					row.branch = stem
89					if j == len(subs)-1 {
90						row.branch = lastStem
91					}
92				}
93			}
94			rows = append(rows, row)
95		}
96		return rows
97	}
98	
99	// shortAgentIDs cuts every ID to one common length, the smallest n >=
100	// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
101	// own length.
102	func shortAgentIDs(ids []string) []string {
103		if len(ids) == 0 {
104			return nil
105		}
106		longest := 0
107		runes := make([][]rune, len(ids))
108		for i, id := range ids {
109			runes[i] = []rune(id)
110			longest = max(longest, len(runes[i]))
111		}
112		cut := func(n int) []string {
113			out := make([]string, len(runes))
114			for i, r := range runes {
115				out[i] = string(r[:min(n, len(r))])
116			}
117			return out
118		}
119		for n := agentIDPrefix; n < longest; n++ {
120			seen := make(map[string]bool, len(ids))
121			distinct := true
122			for _, s := range cut(n) {
123				if seen[s] {
124					distinct = false
125					break
126				}
127				seen[s] = true
128			}
129			if distinct {
130				return cut(n)
131			}
132		}
133		return cut(longest)
134	}
135	
136	// agentColumns describes the agents table. Only Total sorts, largest first;
137	// without a sort the order is the tree. Columns give way on a narrow terminal
138	// in this order: Cache write, Cache read, In, Model, Duration, Tools, State. The ID never does, so two
139	// agents of one type stay apart.
140	func agentColumns() []datatable.Column[agentRow] {
141		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
142			return datatable.Column[agentRow]{
143				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
144				Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
145				Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
146			}
147		}
148		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
149		in.Optional = true
150		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
151		cacheRead.Optional = true
152		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
153		cacheWrite.Optional, cacheWrite.DropFirst = true, true
154		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
155		total.Less = func(a, b agentRow) bool { return a.Tokens.Total() < b.Tokens.Total() }
156		total.DescFirst = true
157	
158		out := count("Out", 7, nil)
159		out.Cell = outCell
160		out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }
161	
162		return []datatable.Column[agentRow]{
163			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
164				Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
165			{Title: "ID", Sizing: datatable.SizingContent, MinWidth: agentIDPrefix, Cell: idCell,
166				Search: func(r agentRow) string { return r.ID },
167				Style:  func(r agentRow) lipgloss.Style { return dimWhen(idCell(r) == noValue || idCell(r) == unknownID) }},
168			stateColumn(), toolsColumn(), durationColumn(),
169			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Optional: true, Cell: modelsCell, Search: modelsCell,
170				Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
171			in, out, cacheRead, cacheWrite, total,
172			{Title: "Share", Sizing: datatable.SizingFixed, MinWidth: len("100.0%"), Cell: shareCell,
173				Style: func(r agentRow) lipgloss.Style { return dimWhen(r.share <= 0) }},
174		}
175	}
176	
177	// stateColumn is the State column: the label is searchable, so `/idle` keeps
178	// the idle agents. Idle is the one state that reads as a warning.
179	func stateColumn() datatable.Column[agentRow] {
180		label := func(r agentRow) string { return r.state.label() }
181		return datatable.Column[agentRow]{
182			Title: "State", Sizing: datatable.SizingFixed, MinWidth: len("running"), Optional: true,
183			Cell: label, Search: label,
184			Style: func(r agentRow) lipgloss.Style {
185				switch r.state {
186				case stateIdle:
187					return theme.SeverityTextStyle("MEDIUM")
188				case stateUnknown:
189					return theme.DimStyle
190				}
191				return lipgloss.NewStyle()
192			},
193		}
194	}
195	
196	// toolsColumn is the Tools column: distinct tool calls read from the transcript.
197	func toolsColumn() datatable.Column[agentRow] {
198		return datatable.Column[agentRow]{
199			Title: "Tools", Sizing: datatable.SizingFixed, MinWidth: 5, Optional: true,
200			Cell:  func(r agentRow) string { return formatTokens(int64(r.ToolCalls)) },
201			Style: func(r agentRow) lipgloss.Style { return dimWhen(r.ToolCalls == 0) },
202		}
203	}
204	
205	// durationColumn is the Duration column: first to last line of the transcript.
206	func durationColumn() datatable.Column[agentRow] {
207		cell := func(r agentRow) string { return formatDuration(r.Duration(), !r.FirstActivity.IsZero()) }
208		return datatable.Column[agentRow]{
209			Title: "Duration", Sizing: datatable.SizingFixed, MinWidth: len("Duration"), Optional: true,
210			Cell:  cell,
211			Style: func(r agentRow) lipgloss.Style { c := cell(r); return dimWhen(c == noValue || c == "0s") },
212		}
213	}
214	
215	// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
216	// anything else keeps the default colour.
217	func dimWhen(dim bool) lipgloss.Style {
218		if dim {
219			return theme.DimStyle
220		}
221		return lipgloss.NewStyle()
222	}
223	
224	// agentSearch is what `/` matches in the Agent column: the role. The full ID is
225	// searched through the ID column.
226	func agentSearch(r agentRow) string { return roleCell(r) }
227	
228	// idCell is the ID column: the short ID of a sub-agent, a dash for the
229	// orchestrator, which has none.
230	func idCell(r agentRow) string {
231		switch {
232		case r.Main:
233			return noValue
234		case r.shortID == "":
235			return unknownID
236		}
237		return r.shortID
238	}
239	
240	// shareCell is the Share column.
241	func shareCell(r agentRow) string { return formatShare(r.share) }
242	
243	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
244	// its branch.
245	func roleCell(r agentRow) string {
246		if r.Main {
247			return orchestratorLabel
248		}
249		typ := r.Type
250		if typ == "" {
251			typ = unknownType
252		}
253		return r.branch + typ
254	}
255	
256	// modelsCell lists the models the agent used.
257	func modelsCell(r agentRow) string {
258		if len(r.Models) == 0 {
259			return noModel
260		}
261		return strings.Join(r.Models, ", ")
262	}
263	
264	// outCell is the output count. A sub-agent still being written is a floor and
265	// says so; the orchestrator never does, its transcript is the one being read.
266	func outCell(r agentRow) string {
267		out := formatTokens(r.Tokens.Output)
268		if !r.Main && r.PartialOutput() {
269			return partialMark + out
270		}
271		return out
272	}
273	
274	// formatTokens renders a count compactly, floored to one decimal: 1099 is
275	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
276	func formatTokens(n int64) string {
277		units := []struct {
278			size   int64
279			suffix string
280		}{
281			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
282		}
283		for _, u := range units {
284			if n < u.size {
285				continue
286			}
287			tenths := n / (u.size / 10) // divide first: n*10 would overflow
288			if tenths >= 1000 {
289				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
290			}
291			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
292		}
293		return fmt.Sprintf("%d", n)
294	}
295	
296	// formatDuration renders a duration compactly; known is false when the
297	// transcript carried no timestamp.
298	func formatDuration(d time.Duration, known bool) string {
299		if !known {
300			return noValue
301		}
302		switch {
303		case d < time.Minute:
304			return fmt.Sprintf("%ds", max(int(d/time.Second), 0))
305		case d < time.Hour:
306			return fmt.Sprintf("%dm%02ds", int(d/time.Minute), int(d%time.Minute/time.Second))
307		case d < 24*time.Hour:
308			return fmt.Sprintf("%dh%02dm", int(d/time.Hour), int(d%time.Hour/time.Minute))
309		case d < 100*24*time.Hour:
310			return fmt.Sprintf("%dd%02dh", int(d/(24*time.Hour)), int(d%(24*time.Hour)/time.Hour))
311		}
312		return ">99d"
313	}
