1	package agentusageview
2	
3	import (
4		"path/filepath"
5		"strconv"
6	
7		"github.com/charmbracelet/lipgloss"
8	
9		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
10		"github.com/anthnel/devdesk/internal/ui/shortcut"
11		"github.com/anthnel/devdesk/internal/ui/theme"
12	)
13	
14	// baseFooterHeight is the blank line and the message line (Rule 124).
15	const baseFooterHeight = 2
16	
17	// View is the table, whatever it holds (Rule 139).
18	func (m Model) View() string {
19		if m.level == levelAgents {
20			return m.agentTable.View()
21		}
22		return m.table.View()
23	}
24	
25	// GetTitle names the view, and the project of the open session at the agents
26	// level (its short ID when the transcript named no project).
27	func (m Model) GetTitle() string {
28		title := theme.IconAgentUsage + " Agent usage"
29		if m.level != levelAgents {
30			return title
31		}
32		leaf := shortID(m.open.ID)
33		if m.open.Project != "" {
34			leaf = filepath.Base(m.open.Project)
35		}
36		return title + " › " + leaf
37	}
38	
39	// shortID is the start of a session ID, as the Session column shows it.
40	func shortID(id string) string {
41		r := []rune(id)
42		return string(r[:min(sessionIDPrefix, len(r))])
43	}
44	
45	// GetIcon returns nothing: the title carries the icon.
46	func (m Model) GetIcon() string { return "" }
47	
48	// GetHeaderInfo counts the sessions on screen, and the ones not listed when
49	// there are some.
50	func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
51		if m.level == levelAgents {
52			return m.agentsHeaderInfo()
53		}
54		info := []shortcut.HeaderInfo{
55			{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
56		}
57		if m.omitted > 0 {
58			info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
59		}
60		return info
61	}
62	
63	// agentsHeaderInfo counts the agents on screen and their tokens, both following
64	// the filter.
65	func (m Model) agentsHeaderInfo() []shortcut.HeaderInfo {
66		rows := m.agentTable.Visible()
67		var total int64
68		for _, r := range rows {
69			total += r.Tokens.Total()
70		}
71		info := []shortcut.HeaderInfo{
72			{Key: "Agents", Value: strconv.Itoa(len(rows)), Style: theme.HeaderValueStyle},
73			{Key: "Tokens", Value: formatTokens(total), Style: theme.HeaderValueStyle},
74			{Key: "Updates", Value: m.updatesState(), Style: theme.HeaderValueStyle},
