321	// Apply folds d in, or replaces everything with it when d.Full(). It returns
322	// ErrStaleDelta, and changes nothing, if d was not read from a.Cursor(). It
323	// takes ownership of d.
324	func (a *Aggregate) Apply(d Delta) error {
325		if !d.valid || d.id != a.id || d.seq != a.seq {
326			return ErrStaleDelta
327		}
328		switch {
329		case d.full:
330			a.t = boundedTable(d.part)
331		case d.part != nil:
332			a.t.mergeCapped(d.part)
333		}
334		a.files, a.metas, a.sessionID = d.files, d.metas, d.sessionID
335		if d.changed {
336			if n := newestMod(d); n.After(a.lastMod) {
337				a.lastMod = n // never moves back when the newest file disappears
338			}
339		}
340		a.fresh = false
341		a.seq++
342		return nil
343	}
